// Emitted on call to camel_folder_summary_replace_flags(), when
// the flags changed.
func (x *FolderSummary) ConnectInfoFlagsChanged(cb *func(FolderSummary, string, uint)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "info-flags-changed", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, UidVarp string, NewFlagsVarp uint) {
		fa := FolderSummary{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, UidVarp, NewFlagsVarp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "info-flags-changed", cbRefPtr)
}

